r=json.loads((old/'REGISTERED.json').read_text(encoding='utf-8'));r.update(version='DIRECT_EXTENSION_V5_SOURCE_CONTACT_DYNAMICS',dynamics_authorized=False,independent_initial_and_chain_review_passed=False,current_code_independently_reviewed=False,new_dynamics_starts=0,prior_dynamics_starts_preserved=23,prior_legacy_postwrap_starts_preserved=8,prior_version='V4.1 one actual failed source-hold diagnostic preserved',revision_reason='V4.1 requested rear torques reached servos but source pose drifted; replace posterior static load allocation with floating-base dynamics and contact-point acceleration compatibility. Fore G/probe/curvature execution retained.')
